-- 1.- Detectar duplicats, s'ha de borrar un dels dos:

SELECT LOWER(codi) AS codi_normalitzat,
         COUNT(*)    AS num_duplicats,
         LISTAGG(codi, ', ') WITHIN GROUP (ORDER BY codi) AS codis_originals
  FROM   IPA_USUARI
  GROUP BY LOWER(codi)
  HAVING COUNT(*) > 1
  ORDER BY num_duplicats DESC;
  
-- 2.- Ara la aplicació nomes cerca en minúscules, per tant tots els usuaris de BBDD haurien de estar en minúscules.

-- #1653 Evitar duplicats de codi de usuari majuscules/minuscules
